sp_widget.client_script:
api.controller=function($scope, $location) {

    var c = this;


	// =====================================================
	// SIDEBAR TOGGLE
	// =====================================================

	c.sidebarCollapsed = false;


	c.toggleSidebar = function() {

		c.sidebarCollapsed =
			!c.sidebarCollapsed;

	};

	// =====================================================
    // SEARCH
    // =====================================================

    c.searchText = '';
    c.searchResults = [];
    c.showSearchResults = false;
    c.searchLoading = false;


    c.search = function() {

        var searchText = (c.searchText || '').trim();


        // Empty search
        if (!searchText) {

            c.searchResults = [];
            c.showSearchResults = false;

            return;

        }


        c.showSearchResults = true;
        c.searchLoading = true;


        c.server.get({

            action: 'search',
            search_text: searchText

        }).then(function(response) {

            c.searchResults =
                response.data.search_results || [];

            c.searchLoading = false;

        });

    };


    // =====================================================
    // CLEAR SEARCH
    // =====================================================

    c.clearSearch = function() {

        c.searchText = '';
        c.searchResults = [];
        c.showSearchResults = false;

    };


    // =====================================================
    // OPEN SEARCH RESULT
    // =====================================================

    c.openSearchResult = function(result) {

        if (!result || !result.page) {
            return;
        }


        window.location.href =
            '?id=' + result.page;

    };


    // =====================================================
    // CLOSE SEARCH WHEN CLICKING OUTSIDE
    // =====================================================

    $scope.$on('$document', function() {

        c.showSearchResults = false;

    });


    // ============================================
    // REFRESH ENTIRE DASHBOARD
    // ============================================

    c.refreshDashboard = function() {

        window.location.reload();

    };


    // ============================================
    // NOTIFICATIONS
    // ============================================

    c.showNotifications = false;

    c.notificationCount = 2;


    c.toggleNotifications = function() {

        c.showNotifications =
            !c.showNotifications;

    };


    // ============================================
    // COMPANY PROFILE
    // ============================================

    c.openCompanyProfile = function() {

        window.location.href =
            '?id=campus360_recruiter_company_profile';

    };


    c.createOpportunity = function() {

        window.location.href =
            '?id=campus360_create_opportunity';

    };

    // CREATE ASSESSMENT
    c.createAssessment = function() {

        $location.search({
            id: 'campus360_create_assessment'
        });

    };

	c.goToAssessments = function() {

		window.location.href =
			'?id=campus360_assessments';

	};

    c.scheduleInterview = function() {

		window.location.href =
			'?id=campus360_recruiter_schedule_new';

	};

	c.goToInterviews = function() {

		window.location.href =
			'?id=campus360_recruiter_interviews_new';

	};



}

sp_widget.css:
/* =========================================================
   CAMPUS360 RECRUITER DASHBOARD
   Fresh dashboard theme
   ========================================================= */

.c360-recruiter {
  min-height: 100vh;
  display: flex;
  background: #f6f5ff;
  color: #101b45;
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.c360-sidebar {
  width: 245px;
  min-width: 245px;
  min-height: 100vh;
  background: #111b45;
  color: #ffffff;
  padding: 18px 14px;
  box-sizing: border-box;
}


.c360-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 8px 22px;
}


.c360-logo {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: #ffffff;
  color: #5146e5;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 21px;
  font-weight: 800;
}


.c360-brand-name {
  font-size: 16px;
  font-weight: 800;
}


.c360-brand-sub {
  font-size: 9px;
  margin-top: 2px;
  color: #b8c1ed;
}


.c360-user-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px;
  margin-bottom: 25px;
  border-radius: 13px;
  background: rgba(255,255,255,0.09);
}


.c360-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #5968f5;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}


.c360-user-name {
  font-size: 12px;
  font-weight: 700;
}


.c360-user-role {
  font-size: 9px;
  color: #b8c1ed;
  margin-top: 3px;
}


.c360-section-title {
  font-size: 9px;
  letter-spacing: 1.3px;
  color: #8f9bd1;
  font-weight: 700;
  margin: 20px 8px 8px;
}


.c360-nav-item {
  height: 40px;
  padding: 0 12px;
  margin-bottom: 4px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  gap: 11px;
  color: #dce1ff;
  font-size: 12px;
  cursor: pointer;
  transition: 0.2s;
}


.c360-nav-item:hover {
  background: rgba(255,255,255,0.08);
}


.c360-nav-item.active {
  background: #5968f5;
  color: #ffffff;
  box-shadow: 0 5px 15px rgba(89,104,245,0.25);
}


/* =========================================================
   MAIN
   ========================================================= */

.c360-main {
  flex: 1;
  min-width: 0;
}


.c360-topbar {
  height: 65px;
  background: #ffffff;
  border-bottom: 1px solid #e6e5f4;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  box-sizing: border-box;
}


.c360-search {
  width: 360px;
  height: 38px;
  border: 1px solid #e2e4f2;
  border-radius: 8px;
  background: #f8f9fd;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  color: #7d87a8;
}


.c360-search input {
  border: 0;
  outline: 0;
  background: transparent;
  width: 100%;
  font-size: 11px;
  color: #27315a;
}


.c360-top-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}


.c360-icon-btn {
  width: 34px;
  height: 34px;
  border: 1px solid #e5e6f3;
  border-radius: 9px;
  background: #ffffff;
  color: #5661e9;
  cursor: pointer;
}


.c360-profile {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: 8px;
}


.c360-profile-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #5968f5;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 700;
}


.c360-profile-name {
  font-size: 11px;
  font-weight: 700;
}


.c360-profile-role {
  font-size: 9px;
  color: #8991ac;
  margin-top: 2px;
}


/* =========================================================
   CONTENT
   ========================================================= */

.c360-content {
  padding: 22px;
}


/* =========================================================
   WELCOME
   ========================================================= */

.c360-welcome {
  min-height: 125px;
  padding: 22px 24px;
  box-sizing: border-box;
  border-radius: 12px;
  background: linear-gradient(
    100deg,
    #f3f1ff,
    #f7f6ff
  );
  border: 1px solid #e6e2ff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}


.c360-eyebrow,
.panel-eyebrow {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
  color: #5957e8;
}


.c360-welcome h1 {
  margin: 6px 0;
  font-size: 22px;
  color: #0e183e;
}


.c360-welcome p {
  margin: 0;
  color: #66708f;
  font-size: 11px;
}


.c360-company-badge {
  background: #ffffff;
  border: 1px solid #e3e4ef;
  border-radius: 10px;
  padding: 13px 22px;
  text-align: right;
}


.company-label {
  font-size: 8px;
  color: #8b93ad;
  font-weight: 700;
}


.company-name {
  margin-top: 5px;
  font-size: 12px;
  font-weight: 800;
  color: #2833a8;
}


/* =========================================================
   STAT CARDS
   ========================================================= */

.c360-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}


.c360-stat-card {
  min-height: 125px;
  padding: 16px;
  box-sizing: border-box;
  border-radius: 11px;
  background: #ffffff;
  border: 1px solid #e4e5f1;
  box-shadow: 0 2px 8px rgba(31, 41, 85, 0.03);
}


.stat-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #65708f;
  font-size: 10px;
  font-weight: 600;
}


.stat-icon {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}


.stat-purple .stat-icon {
  background: #ecebff;
  color: #5b55e8;
}


.stat-blue .stat-icon {
  background: #e6f0ff;
  color: #4684e8;
}


.stat-violet .stat-icon {
  background: #f0e8ff;
  color: #8a55df;
}


.stat-green .stat-icon {
  background: #e4f8ee;
  color: #27a46b;
}


.stat-number {
  font-size: 25px;
  font-weight: 800;
  color: #101a42;
  margin-top: 12px;
}


.stat-bottom {
  font-size: 9px;
  color: #929ab1;
  margin-top: 4px;
}


.stat-bottom span {
  float: right;
  color: #514fe1;
  font-weight: 700;
}


/* =========================================================
   PANELS
   ========================================================= */

.c360-grid-two {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}


.c360-panel {
  background: #ffffff;
  border: 1px solid #e4e5f1;
  border-radius: 11px;
  padding: 18px;
  box-sizing: border-box;
  box-shadow: 0 2px 8px rgba(31,41,85,0.025);
}


.panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}


.panel-header h2 {
  margin: 5px 0 0;
  font-size: 14px;
  color: #101a42;
}


.view-all {
  border: 0;
  background: transparent;
  color: #5554e6;
  font-size: 9px;
  font-weight: 700;
  cursor: pointer;
}


/* =========================================================
   OPPORTUNITY PLACEHOLDER
   ========================================================= */

.opportunity-placeholder {
  min-height: 145px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  color: #858da7;
  text-align: left;
}


.placeholder-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: #eeedff;
  color: #5a58e8;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
}


.opportunity-placeholder strong,
.empty-interviews strong {
  color: #39415f;
  font-size: 11px;
}


.opportunity-placeholder p,
.empty-interviews p {
  margin: 5px 0 0;
  font-size: 9px;
  color: #9299ae;
}


/* =========================================================
   PIPELINE
   ========================================================= */

.pipeline {
  min-height: 145px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 28px;
}


.pipeline-circle {
  width: 105px;
  height: 105px;
  border-radius: 50%;
  border: 10px solid #e8eaff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}


.pipeline-circle strong {
  font-size: 22px;
  color: #171f49;
}


.pipeline-circle span {
  font-size: 8px;
  color: #9299ae;
  margin-top: 2px;
}


.pipeline-legend {
  font-size: 10px;
  color: #6e7690;
}


.pipeline-legend div {
  margin: 11px 0;
  display: flex;
  align-items: center;
  gap: 7px;
}


.pipeline-legend strong {
  margin-left: 15px;
  color: #323b5c;
}


.legend-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}


.pending {
  background: #f2ae38;
}


.submitted {
  background: #929aaf;
}


.selected {
  background: #5b5ce8;
}


/* =========================================================
   TABLE
   ========================================================= */

.empty-table {
  margin-top: 18px;
}


.table-header {
  display: grid;
  grid-template-columns: 1.5fr 1.2fr 1fr .6fr;
  padding: 10px 4px;
  border-bottom: 1px solid #ececf5;
  font-size: 8px;
  color: #8c94aa;
  font-weight: 700;
}


.empty-row {
  min-height: 90px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: #969db1;
}


/* =========================================================
   INTERVIEWS
   ========================================================= */

.empty-interviews {
  min-height: 130px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.quick-actions {
  margin-bottom: 20px;
}


.action-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 15px;
}


.action-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px;
  background: #f8f8ff;
  border: 1px solid #e8e7f6;
  border-radius: 10px;
  text-align: left;
  cursor: pointer;
}


.action-card:hover {
  border-color: #b9b6f6;
  background: #f4f3ff;
}


.action-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 9px;
  background: #e8e7ff;
  color: #5755e6;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  font-weight: 700;
}


.action-card strong {
  display: block;
  color: #283153;
  font-size: 10px;
}


.action-card span {
  display: block;
  margin-top: 3px;
  color: #8a92a9;
  font-size: 8px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

  .c360-sidebar {
    width: 210px;
    min-width: 210px;
  }

  .c360-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .c360-grid-two {
    grid-template-columns: 1fr;
  }

}


@media (max-width: 700px) {

  .c360-sidebar {
    display: none;
  }

  .c360-content {
    padding: 12px;
  }

  .c360-topbar {
    padding: 0 12px;
  }

  .c360-search {
    width: 220px;
  }

  .c360-welcome {
    flex-direction: column;
    align-items: flex-start;
    gap: 15px;
  }

  .c360-company-badge {
    text-align: left;
  }

  .c360-stats {
    grid-template-columns: 1fr;
  }

  .action-grid {
    grid-template-columns: 1fr;
  }

}



/* =========================================================
   CAMPUS360 STUDENT THEME
   Recruiter Dashboard Color Override
   ========================================================= */

/* ---------- MAIN BACKGROUND ---------- */

.c360-recruiter {
  background: #f5f7fb !important;
  color: #101b45 !important;
}


/* =========================================================
   SIDEBAR - LIGHT STUDENT DASHBOARD STYLE
   ========================================================= */

.c360-sidebar {
  background: #efedff !important;
  color: #20244f !important;
  border-right: 1px solid #dedcff;
}

/* Logo */

.c360-logo {
  background: #5548e8 !important;
  color: #ffffff !important;
}

/* Brand */

.c360-brand-name {
  color: #20244f !important;
}

.c360-brand-sub {
  color: #625e91 !important;
}


/* Recruiter user card */

.c360-user-card {
  background: #ffffff !important;
  border: 1px solid #dddafe;
  box-shadow: 0 2px 8px rgba(70, 65, 160, 0.05);
}

.c360-user-name {
  color: #20244f !important;
}

.c360-user-role {
  color: #77739a !important;
}

.c360-avatar {
  background: #5a54e8 !important;
  color: #ffffff !important;
}


/* Section headings */

.c360-section-title {
  color: #7771a8 !important;
}


/* Navigation */

.c360-nav-item {
  color: #34365f !important;
}

.c360-nav-item:hover {
  background: #e4e1ff !important;
  color: #5148df !important;
}


/* Active navigation */

.c360-nav-item.active {
  background: #ffffff !important;
  color: #5148df !important;
  box-shadow: 0 2px 8px rgba(80, 72, 220, 0.08) !important;
}


/* =========================================================
   TOP BAR
   ========================================================= */

.c360-topbar {
  background: #ffffff !important;
  border-bottom: 1px solid #e3e4ef !important;
}

.c360-search {
  background: #f8f9fd !important;
  border-color: #dddff0 !important;
}

.c360-search input {
  color: #30345c !important;
}

.c360-icon-btn {
  background: #ffffff !important;
  border-color: #e1e2ef !important;
  color: #554de3 !important;
}

.c360-profile-avatar {
  background: #5a54e8 !important;
}

.c360-profile-name {
  color: #25294f !important;
}

.c360-profile-role {
  color: #858aa3 !important;
}


/* =========================================================
   CONTENT
   ========================================================= */

.c360-content {
  background: #f5f7fb !important;
}


/* =========================================================
   WELCOME CARD
   ========================================================= */

.c360-welcome {
  background: linear-gradient(
    100deg,
    #f2f0ff,
    #f7f6ff
  ) !important;

  border: 1px solid #dedbff !important;
}

.c360-eyebrow,
.panel-eyebrow {
  color: #5148e5 !important;
}

.c360-welcome h1 {
  color: #10183d !important;
}

.c360-welcome p {
  color: #68718e !important;
}

.c360-company-badge {
  background: #ffffff !important;
  border-color: #e0e1ee !important;
}

.company-label {
  color: #858ba5 !important;
}

.company-name {
  color: #403bc2 !important;
}


/* =========================================================
   STAT CARDS
   MATCH STUDENT DASHBOARD COLORS
   ========================================================= */

.c360-stat-card {
  border-radius: 11px !important;
  box-shadow: none !important;
}


/* 1 - Placement Opportunities
   Student dashboard = GREEN / MINT */

.c360-stat-card.stat-purple {
  background: #ddfbf0 !important;
  border-color: #a9efda !important;
}

.c360-stat-card.stat-purple .stat-icon {
  background: #ffffff !important;
  color: #514de5 !important;
}


/* 2 - Applications
   Student dashboard = BLUE */

.c360-stat-card.stat-blue {
  background: #e3efff !important;
  border-color: #bdd8ff !important;
}

.c360-stat-card.stat-blue .stat-icon {
  background: #ffffff !important;
  color: #4b83e8 !important;
}


/* 3 - Interviews
   Student dashboard = LIGHT PURPLE */

.c360-stat-card.stat-violet {
  background: #eee5ff !important;
  border-color: #d7c3ff !important;
}

.c360-stat-card.stat-violet .stat-icon {
  background: #ffffff !important;
  color: #8755dd !important;
}


/* 4 - Offers
   Student dashboard = PEACH */

.c360-stat-card.stat-green {
  background: #ffe9e1 !important;
  border-color: #ffcfc0 !important;
}

.c360-stat-card.stat-green .stat-icon {
  background: #ffffff !important;
  color: #f06c55 !important;
}


/* Stat text */

.stat-top {
  color: #56617e !important;
}

.stat-number {
  color: #101a42 !important;
}

.stat-bottom {
  color: #7d86a0 !important;
}

.stat-bottom span {
  color: #514de1 !important;
}


/* =========================================================
   MAIN PANELS
   ========================================================= */

.c360-panel {
  background: #ffffff !important;
  border-color: #e1e3ef !important;
  box-shadow: 0 2px 8px rgba(35, 43, 85, 0.025) !important;
}

.panel-header h2 {
  color: #101a42 !important;
}

.view-all {
  color: #514de1 !important;
}


/* =========================================================
   OPPORTUNITY PLACEHOLDER
   ========================================================= */

.placeholder-icon {
  background: #eeecff !important;
  color: #5853e5 !important;
}

.opportunity-placeholder strong,
.empty-interviews strong {
  color: #343b5c !important;
}

.opportunity-placeholder p,
.empty-interviews p {
  color: #9299ae !important;
}


/* =========================================================
   APPLICATION PIPELINE
   ========================================================= */

.pipeline-circle {
  border-color: #e6e8ff !important;
}

.pipeline-circle strong {
  color: #171f49 !important;
}

.pipeline-circle span {
  color: #9299ae !important;
}

.pipeline-legend {
  color: #6e7690 !important;
}

.pipeline-legend strong {
  color: #323b5c !important;
}

.pending {
  background: #f2ae38 !important;
}

.submitted {
  background: #929aaf !important;
}

.selected {
  background: #5b5ce8 !important;
}


/* =========================================================
   RECENT APPLICATIONS
   ========================================================= */

.table-header {
  border-bottom-color: #e7e8f1 !important;
  color: #8c94aa !important;
}

.empty-row {
  color: #969db1 !important;
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.action-card {
  background: #f9f9ff !important;
  border-color: #e5e4f5 !important;
}

.action-card:hover {
