/* =========================================
   RECENT APPLICATIONS
========================================= */

.application-table {
  width: 100%;
  margin-top: 18px;
}


/* TABLE HEADER */

.application-table .table-header {
  display: grid;
  grid-template-columns: 1.3fr 1.4fr 1fr 0.7fr;

  align-items: center;

  padding: 0 8px 10px;

  border-bottom: 1px solid #e8e8f5;

  color: #7c7ca0;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 0.08em;
}


/* APPLICATION ROW */

.application-row {
  display: grid;

  grid-template-columns: 1.3fr 1.4fr 1fr 0.7fr;

  align-items: center;

  min-height: 48px;

  padding: 8px;

  border-bottom: 1px solid #f0f0f7;
}


/* STUDENT */

.student-cell strong {
  font-size: 12px;
  font-weight: 600;
  color: #11113d;
}


/* ROLE */

.role-cell {
  font-size: 11px;
  color: #55557a;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}


/* STATUS */

.status-cell {
  display: flex;
  align-items: center;
}


/* STATUS BADGE */

.application-status {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  padding: 4px 9px;

  border-radius: 6px;

  font-size: 9px;
  font-weight: 600;
}


/* PENDING */

.status-pending {
  background: #fff4dc;
  color: #c47b00;
}


/* SUBMITTED */

.status-submitted {
  background: #eeeaff;
  color: #6254e8;
}


/* SELECTED */

.status-selected {
  background: #dcf8ee;
  color: #16845e;
}


/* REJECTED */

.status-rejected {
  background: #ffe7e4;
  color: #d6534b;
}


/* ACTION */

.action-cell {
  display: flex;
  justify-content: flex-end;
}


/* VIEW BUTTON */

.application-view {
  border: none;

  background: transparent;

  color: #5546e8;

  font-size: 10px;
  font-weight: 600;

  cursor: pointer;

  padding: 4px 0;
}

.application-view:hover {
  text-decoration: underline;
}


/* =========================================
   EMPTY STATE
========================================= */

.empty-table {
  width: 100%;
  margin-top: 18px;
}

.empty-table .table-header {
  display: grid;

  grid-template-columns: 1.3fr 1.4fr 1fr 0.7fr;

  padding: 0 8px 10px;

  border-bottom: 1px solid #e8e8f5;

  color: #7c7ca0;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 0.08em;
}

.empty-row {
  text-align: center;

  padding: 35px 10px;

  color: #9292b2;

  font-size: 11px;
}


/* =========================================
   PLACEMENT OPPORTUNITIES
   ========================================= */

.opportunity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 14px;
}

.opportunity-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid #e8e7f5;
  border-radius: 12px;
  background: #ffffff;
  transition: all 0.2s ease;
}

.opportunity-item:hover {
  border-color: #d8d4ff;
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.08);
  transform: translateY(-1px);
}

/* Opportunity icon */

.opportunity-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;
  background: #f0edff;
  color: #5b4df6;

  font-size: 17px;
}

/* Opportunity information */

.opportunity-info {
  flex: 1;
  min-width: 0;
}

.opportunity-info strong {
  display: block;

  font-size: 15px;
  font-weight: 600;
  color: #111827;

  margin-bottom: 4px;
}

.opportunity-info p {
  margin: 3px 0;

  font-size: 12px;
  line-height: 1.5;
  color: #64748b;
}

/* Opportunity ID / type */

.opportunity-info p:first-of-type {
  color: #6366f1;
  font-size: 11px;
  font-weight: 500;
}

/* Location / CTC */

.opportunity-info p:nth-of-type(2) {
  color: #475569;
}

/* Deadline */

.opportunity-info p:nth-of-type(3) {
  color: #64748b;
}

/* Status */

.opportunity-status {
  flex-shrink: 0;

  padding: 5px 10px;

  border-radius: 20px;

  background: #ecfdf5;
  color: #059669;

  font-size: 11px;
  font-weight: 600;

  white-space: nowrap;
}

/* =========================================
   EMPTY STATE
   ========================================= */

.opportunity-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;

  min-height: 130px;

  text-align: left;
  color: #64748b;
}

.opportunity-placeholder .placeholder-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background: #f0edff;
  color: #5b4df6;

  font-size: 18px;
}

.opportunity-placeholder strong {
  display: block;

  color: #334155;
  font-size: 14px;

  margin-bottom: 4px;
}

.opportunity-placeholder p {
  margin: 0;

  font-size: 12px;
  color: #94a3b8;
}



/* =========================================
   RECENT APPLICATIONS TABLE
   ========================================= */

.application-table {
  width: 100%;
  margin-top: 18px;
}


/* =========================================
   TABLE HEADER
   ========================================= */

.table-header {
  display: grid;

  /* Student | Role | Status | Action */
  grid-template-columns: 1.5fr 1.2fr 1fr 0.8fr;

  align-items: center;

  padding: 0 8px 10px;

  border-bottom: 1px solid #e6e7f2;

  color: #777b9a;

  font-size: 10px;
  font-weight: 600;

  letter-spacing: 0.5px;
}


/* Student header */
.table-header span:nth-child(1) {
  text-align: left;
}


/* Role, Status and Action headers */
.table-header span:nth-child(2),
.table-header span:nth-child(3),
.table-header span:nth-child(4) {
  text-align: center;
}


/* =========================================
   APPLICATION ROW
   ========================================= */

.application-row {
  display: grid;

  /* Must match table-header exactly */
  grid-template-columns: 1.5fr 1.2fr 1fr 0.8fr;

  align-items: center;

  min-height: 46px;

  padding: 0 8px;

  border-bottom: 1px solid #eeeeF5;

  font-size: 12px;
}


/* Remove border from last row */
.application-row:last-child {
  border-bottom: none;
}


/* =========================================
   STUDENT
   ========================================= */

.student-cell {
  text-align: left;
}

.student-cell strong {
  color: #111a4d;

  font-size: 12px;

  font-weight: 600;
}


/* =========================================
   ROLE
   ========================================= */

.role-cell {
  color: #4e5680;

  font-size: 11px;

  text-align: center;

  white-space: nowrap;
}


/* =========================================
   STATUS
   ========================================= */

.status-cell {
  display: flex;

  align-items: center;

  justify-content: center;
}


/* Status badge */
.application-status {
  display: inline-flex;

  align-items: center;

  justify-content: center;

  padding: 4px 9px;

  border-radius: 6px;

  font-size: 10px;

  font-weight: 500;

  line-height: 1;

  white-space: nowrap;
}


/* =========================================
   PENDING
   ========================================= */

.status-pending {
  background: #fff3d6;

  color: #c98200;
}


/* =========================================
   SUBMITTED
   ========================================= */

.status-submitted {
  background: #eee9ff;

  color: #635bdb;
}


/* =========================================
   SELECTED
   ========================================= */

.status-selected {
  background: #dcf8ed;

  color: #16845c;
}


/* =========================================
   REJECTED
   ========================================= */

.status-rejected {
  background: #ffe5e5;

  color: #d84b4b;
}


/* =========================================
   ACTION
   ========================================= */

.action-cell {
  display: flex;

  align-items: center;

  justify-content: center;
}


/* View button */
.application-view {
  border: none;

  background: transparent;

  color: #5b52e8;

  font-size: 10px;

  font-weight: 500;

  cursor: pointer;

  padding: 4px 0;

  text-align: center;

  white-space: nowrap;
}


/* Hover */
.application-view:hover {
  color: #3f36c9;

  text-decoration: underline;
}


/* =========================================
   EMPTY TABLE
   ========================================= */

.empty-table {
  width: 100%;

  margin-top: 18px;
}


.empty-row {
  display: flex;

  align-items: center;

  justify-content: center;

  min-height: 90px;

  color: #9a9db5;

  font-size: 11px;

  text-align: center;
}




/* =========================================
   UPCOMING INTERVIEWS
   ========================================= */

.upcoming-interviews-panel {
  min-height: 250px;
}


/* =========================================
   INTERVIEW LIST
   ========================================= */

.interview-list {
  width: 100%;
  margin-top: 18px;
}


/* =========================================
   INTERVIEW CARD
   ========================================= */

.interview-card {
  display: flex;
  align-items: center;

  width: 100%;
  min-height: 78px;

  padding: 12px 14px;

  background: #ffffff;

  border: 1px solid #eeeef6;
  border-radius: 10px;

  box-sizing: border-box;

  transition: all 0.2s ease;
}


/* Multiple interview cards */
.interview-card + .interview-card {
  margin-top: 10px;
}


/* Hover */
.interview-card:hover {
  border-color: #dcd9ff;
  box-shadow: 0 4px 12px rgba(75, 70, 180, 0.06);
}


/* =========================================
   INTERVIEW ICON
   ========================================= */

.interview-icon {
  width: 38px;
  height: 38px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-right: 12px;

  border-radius: 9px;

  background: #f0edff;

  color: #5b52e8;

  font-size: 19px;
  font-weight: 500;
}


/* =========================================
   INTERVIEW INFORMATION
   ========================================= */

.interview-info {
  flex: 1;
  min-width: 0;
}


/* Student */
.interview-student {
  color: #111a4d;

  font-size: 13px;
  font-weight: 600;

  line-height: 1.3;
}


/* Opportunity */
.interview-role {
  margin-top: 3px;

  color: #596080;

  font-size: 11px;

  line-height: 1.3;
}


/* Date */
.interview-date {
  margin-top: 5px;

  color: #777b9a;

  font-size: 10px;

  line-height: 1.3;
}


/* =========================================
   INTERVIEW MODE
   ========================================= */

.interview-mode {
  flex-shrink: 0;

  margin-left: 12px;

  padding: 5px 9px;

  border-radius: 6px;

  background: #f5f4ff;

  color: #5b52e8;

  font-size: 10px;
  font-weight: 500;

  white-space: nowrap;
}


/* =========================================
   INTERVIEW STATUS
   ========================================= */

.interview-status {
  flex-shrink: 0;

  min-width: 70px;

  margin-left: 10px;

  padding: 6px 10px;

  border-radius: 6px;

  background: #eee9ff;

  color: #635bdb;

  font-size: 10px;

  font-weight: 500;

  text-align: center;

  white-space: nowrap;
}


/* =========================================
   EMPTY STATE
   ========================================= */

.empty-interviews {
  min-height: 160px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  text-align: center;
}


/* Empty icon */
.empty-interviews .placeholder-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 10px;

  border-radius: 10px;

  background: #f0edff;

  color: #5b52e8;

  font-size: 20px;
}


/* Empty title */
.empty-interviews strong {
  color: #111a4d;

  font-size: 12px;
}


/* Empty description */
.empty-interviews p {
  margin: 5px 0 0;

  color: #9a9db5;

  font-size: 10px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 700px) {

  .interview-card {
    flex-wrap: wrap;
  }

  .interview-info {
    width: calc(100% - 50px);
  }

  .interview-mode {
    margin-left: 50px;
    margin-top: 8px;
  }

  .interview-status {
    margin-top: 8px;
  }

}


/* =====================================================
   QUICK ACTIONS PANEL
===================================================== */

.quick-actions-panel {
    width: 100%;
    height: auto !important;
    min-height: 0 !important;

    padding: 14px 16px !important;

    box-sizing: border-box;

    overflow: hidden;
}


/* =====================================================
   QUICK ACTIONS HEADER
===================================================== */

.quick-actions-panel .panel-header {
    margin-bottom: 10px;
    padding: 0;
}

.quick-actions-panel .panel-eyebrow {
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 1px;
    color: #5267e8;
}

.quick-actions-panel .panel-header h2 {
    margin: 3px 0 0;

    font-size: 13px;
    font-weight: 700;

    color: #102a56;
}


/* =====================================================
   QUICK ACTIONS GRID
===================================================== */

.quick-actions-grid {
    display: grid !important;

    grid-template-columns:
        repeat(3, minmax(0, 1fr)) !important;

    gap: 10px !important;

    width: 100%;

    align-items: stretch;
}


/* =====================================================
   QUICK ACTION CARD
===================================================== */

.quick-action-card {
    width: 100% !important;

    min-width: 0 !important;

    height: 58px !important;
    min-height: 58px !important;

    box-sizing: border-box;

    padding: 9px 11px !important;

    border: 1px solid #dfe4f2 !important;
    border-radius: 8px !important;

    background: #ffffff !important;

    display: flex !important;
    align-items: center !important;

    gap: 9px !important;

    text-align: left;

    cursor: pointer;

    overflow: hidden;

    transition: 0.15s ease;
}


/* =====================================================
   HOVER
===================================================== */

.quick-action-card:hover {
    background: #f8f9ff !important;

    border-color: #cbd4f5 !important;
}


/* =====================================================
   ICON
===================================================== */

.quick-action-icon {
    width: 28px !important;
    height: 28px !important;

    min-width: 28px !important;
    flex-shrink: 0 !important;

    border-radius: 7px;

    background: #f0efff;

    color: #5267e8;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    font-size: 14px;
}


/* =====================================================
   CONTENT
===================================================== */

.quick-action-content {
    min-width: 0 !important;

    flex: 1 !important;

    display: flex !important;
    flex-direction: column !important;

    justify-content: center;

    overflow: hidden;
}


.quick-action-content strong {
    display: block;

    font-size: 9px;

    font-weight: 700;

    color: #173b70;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


.quick-action-content span {
    display: block;

    margin-top: 2px;

    font-size: 7px;

    line-height: 1.3;

    color: #8a96aa;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


/* =====================================================
   ARROW
===================================================== */

.quick-action-arrow {
    flex-shrink: 0;

    font-size: 11px;

    color: #5267e8;
}


/* =====================================================
   MOBILE
===================================================== */

@media (max-width: 768px) {

    .quick-actions-grid {
        grid-template-columns: 1fr !important;
    }

    .quick-action-card {
        height: 58px !important;
    }

}
/* =====================================================
   DASHBOARD PANEL
===================================================== */

.c360-panel {
