    padding: 0 12px 12px;

    overflow: hidden;
}
























/* =====================================================
   QUICK ACTION TEXT — INCREASED SIZE
===================================================== */

.quick-action-content strong {
    display: block;

    font-size: 12px !important;
    line-height: 1.25;

    font-weight: 700;

    color: #173b70;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


.quick-action-content span {
    display: block;

    margin-top: 3px;

    font-size: 9px !important;
    line-height: 1.3;

    color: #71809c;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


.quick-action-arrow {
    flex-shrink: 0;

    font-size: 13px !important;

    color: #5267e8;
}



























/* =====================================================
   APPLICATION STATUS PANEL
===================================================== */

.application-status-panel {
    height: 380px;
    min-height: 380px;

    display: flex;
    flex-direction: column;

    box-sizing: border-box;
}


/* =====================================================
   HEADER
===================================================== */

.application-status-panel .panel-header {
    padding: 16px 18px 0;

    display: flex;
    align-items: flex-start;
    justify-content: space-between;

    flex-shrink: 0;
}


.application-status-panel .panel-eyebrow {
    font-size: 9px;

    font-weight: 700;

    letter-spacing: 1px;

    color: #5267e8;
}


.application-status-panel .panel-header h2 {
    margin: 4px 0 0;

    font-size: 15px;

    font-weight: 700;

    color: #102a56;
}


/* =====================================================
   VIEW DETAILS
===================================================== */

.application-view-details {
    margin-top: 1px;

    font-size: 10px;

    font-weight: 600;

    color: #5267e8;

    text-decoration: none;

    white-space: nowrap;

    cursor: pointer;
}


.application-view-details:hover {
    color: #3047c8;

    text-decoration: none;
}


/* =====================================================
   STATUS CONTENT
===================================================== */

.application-status-content {

    flex: 1;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 30px;

    padding: 10px 20px 25px;
}


/* =====================================================
   DONUT
===================================================== */

.application-donut {

    width: 105px;
    height: 105px;

    flex-shrink: 0;

    border-radius: 50%;

    background:
        conic-gradient(
            #6268e8 0deg,
            #6268e8 360deg
        );

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    position: relative;
}


/* WHITE INNER CIRCLE */

.application-donut::after {

    content: "";

    position: absolute;

    width: 81px;
    height: 81px;

    background: #ffffff;

    border-radius: 50%;
}


/* NUMBER */

.donut-number {

    position: relative;

    z-index: 2;

    font-size: 24px;

    font-weight: 700;

    line-height: 1;

    color: #102a56;
}


/* LABEL */

.donut-label {

    position: relative;

    z-index: 2;

    margin-top: 6px;

    font-size: 9px;

    color: #8793aa;
}


/* =====================================================
   LEGEND
===================================================== */

.application-status-legend {

    display: flex;

    flex-direction: column;

    gap: 14px;

    min-width: 125px;
}


.status-legend-row {

    display: grid;

    grid-template-columns:
        9px 1fr auto;

    align-items: center;

    column-gap: 8px;
}


.status-dot {

    width: 8px;
    height: 8px;

    border-radius: 50%;
}


.pending-dot {
    background: #f5a623;
}


.submitted-dot {
    background: #98a2b5;
}


.selected-dot {
    background: #5c63e8;
}


.status-name {

    font-size: 11px;

    color: #66758f;
}


.status-legend-row strong {

    font-size: 11px;

    font-weight: 700;

    color: #193964;
}


.shortlisted-dot {
