    font-size: 11px;
}


/* ============================================
   NOTIFICATION DROPDOWN
============================================ */

.notification-dropdown {

    position: absolute;

    top: 66px;

    right: 145px;

    width: 330px;

    background: white;

    border: 1px solid #dfe4f2;

    border-radius: 12px;

    box-shadow:
        0 12px 30px rgba(30, 50, 100, 0.14);

    z-index: 1000;

    overflow: hidden;
}


/* HEADER */

.notification-header {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 15px 17px;

    border-bottom: 1px solid #edf0f6;

}


.notification-header strong {

    font-size: 14px;

    color: #173766;
}


.notification-header span {

    background: #eeeefe;

    color: #5752e8;

    border-radius: 12px;

    padding: 3px 8px;

    font-size: 10px;

    font-weight: 700;
}


/* ITEM */

.notification-item {

    display: flex;

    gap: 11px;

    padding: 14px 17px;

    border-bottom: 1px solid #f0f2f7;
}


.notification-dot {

    width: 8px;

    height: 8px;

    background: #5a55e8;

    border-radius: 50%;

    margin-top: 5px;

    flex-shrink: 0;
}


.notification-item strong {

    display: block;

    font-size: 12px;

    color: #193762;

    margin-bottom: 4px;
}


.notification-item span {

    display: block;

    font-size: 10px;

    line-height: 1.5;

    color: #7b89a4;
}


/* EMPTY */

.notification-empty {

    padding: 25px;

    text-align: center;

    font-size: 12px;

    color: #7d89a3;
}


/* ============================================
   SEARCH WRAPPER
============================================ */

.c360-search-wrapper {

    position: relative;

    width: 430px;

}


/* ============================================
   SEARCH RESULTS
============================================ */

.c360-search-results {

    position: absolute;

    top: 52px;

    left: 0;

    width: 100%;

    background: #ffffff;

    border: 1px solid #dfe4f2;

    border-radius: 12px;

    box-shadow:
        0 12px 30px rgba(30, 50, 100, 0.14);

    overflow: hidden;

    z-index: 2000;

}


/* ============================================
   RESULT
============================================ */

.search-result {

    display: flex;

    align-items: center;

    gap: 12px;

    padding: 12px 14px;

    cursor: pointer;

    border-bottom: 1px solid #f0f2f7;

}


.search-result:hover {

    background: #f7f8ff;

}


.search-result:last-child {

    border-bottom: none;

}


/* ============================================
   RESULT ICON
============================================ */

.search-result-icon {

    width: 34px;

    height: 34px;

    border-radius: 8px;

    background: #eeeeff;

    color: #5752e8;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 14px;

    flex-shrink: 0;

}


/* ============================================
   RESULT CONTENT
============================================ */

.search-result-content {

    flex: 1;

    min-width: 0;

}


.search-result-content strong {

    display: block;

    font-size: 12px;

    color: #173766;

    margin-bottom: 3px;

}


.search-result-content span {

    display: block;

    font-size: 10px;

    color: #7b89a4;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;

}


/* ============================================
   RESULT TYPE
============================================ */

.search-result-type {

    font-size: 9px;

    font-weight: 600;

    color: #5752e8;

    background: #eeeeff;

    padding: 4px 7px;

    border-radius: 10px;

}


/* ============================================
   NO RESULTS
============================================ */

.search-no-results {

    padding: 22px;

    text-align: center;

    font-size: 11px;

    color: #7b89a4;

}


.search-no-results strong {

    color: #173766;

}


/* =====================================================
   SEARCH
===================================================== */

.c360-search-wrapper {
    position: relative;
    width: 430px;
}


.c360-search-box {
    height: 48px;

    background: #ffffff;

    border: 1px solid #d9def3;

    border-radius: 10px;

    display: flex;
    align-items: center;

    padding: 0 14px;

    box-sizing: border-box;
}


.c360-search-box:focus-within {
    border-color: #5267e8;

    box-shadow:
        0 0 0 3px rgba(82, 103, 232, 0.08);
}


.c360-search-icon {
    font-size: 22px;

    color: #5267e8;

    margin-right: 10px;
}


.c360-search-input {
    border: none !important;

    outline: none !important;

    box-shadow: none !important;

    background: transparent !important;

    width: 100%;

    height: 100%;

    font-size: 15px;

    color: #173b70;
}


.c360-search-input::placeholder {
    color: #8793ad;
}


.c360-search-clear {
    border: none;

    background: transparent;

    color: #7b88a5;

    font-size: 20px;

    cursor: pointer;

    padding: 0 4px;
}


/* =====================================================
   SEARCH RESULTS
===================================================== */

.c360-search-results {

    position: absolute;

    top: 55px;

    left: 0;

    width: 100%;

    background: #ffffff;

    border: 1px solid #dce2f2;

    border-radius: 12px;

    box-shadow:
        0 12px 30px rgba(30, 50, 100, 0.12);

    overflow: hidden;

    z-index: 9999;
}


.search-result {

    display: flex;

    align-items: center;

    gap: 12px;

    padding: 13px 15px;

    cursor: pointer;

    border-bottom: 1px solid #f0f2f8;
}


.search-result:last-child {
    border-bottom: none;
}


.search-result:hover {
    background: #f7f8ff;
}


.search-result-icon {

    width: 34px;

    height: 34px;

    border-radius: 8px;

    background: #eeedff;

    color: #5267e8;

    display: flex;

    align-items: center;

    justify-content: center;

    flex-shrink: 0;
}


.search-result-content {

    display: flex;

    flex-direction: column;

    gap: 4px;

    flex: 1;

    min-width: 0;
}


.search-result-content strong {

    font-size: 14px;

    color: #102a56;
}


.search-result-content span {

    font-size: 11px;

    color: #7a89a5;
}


.search-result-type {

    font-size: 10px;

    font-weight: 600;

    color: #5267e8;

    background: #f0efff;

    padding: 5px 8px;

    border-radius: 10px;
}


.search-message {

    padding: 20px;

    text-align: center;

    font-size: 13px;

    color: #8491ad;
}


.search-message strong {
    color: #173b70;
}






/* =========================================================
   SIDEBAR TOGGLE BUTTON
========================================================= */

.c360-menu-btn {

    width: 42px;
    height: 42px;

    border: 1px solid #dce3ef;

    border-radius: 9px;

    background: #ffffff;

    color: #182a4d;

    font-size: 21px;

    display: flex;

    align-items: center;

    justify-content: center;

    cursor: pointer;

    transition: all 0.2s ease;

    flex-shrink: 0;
}


.c360-menu-btn:hover {

    background: #f3f6ff;

    border-color: #536dfe;

    color: #536dfe;

}


/* =========================================================
   SIDEBAR TRANSITION
========================================================= */

.c360-sidebar {

    width: 250px;

    flex-shrink: 0;

    transition:
        width 0.25s ease,
        padding 0.25s ease;

    overflow: hidden;

}


/* =========================================================
   MAIN CONTENT TRANSITION
========================================================= */

.c360-main {

    flex: 1;

    min-width: 0;

    transition:
        margin-left 0.25s ease,
        width 0.25s ease;

}


/* =========================================================
   COLLAPSED SIDEBAR
========================================================= */

.c360-recruiter.sidebar-collapsed
.c360-sidebar {

    width: 0;

    padding-left: 0;

    padding-right: 0;

}


/* =========================================================
   KEEP MAIN CONTENT FULL WIDTH
========================================================= */

.c360-recruiter.sidebar-collapsed
.c360-main {

    width: 100%;

}

sp_widget.script:
(function() {

    // Test recruiter/company
    data.recruiter_name = 'Ananya Mehta';
    data.recruiter_id = 'RCR001';

    // TechNova Solutions - CMP001
    var companySysId = 'e9268662acd303107f44b432e349694b';

    // Company
    var company = new GlideRecord('x_snc_campus360_company_master');

    if (company.get(companySysId)) {
        data.company_name = company.getValue('company_name');
        data.company_id = company.getValue('company_id');
    }

	// =====================================================
	// GLOBAL SEARCH
	// =====================================================

	if (input && input.action == 'search') {

		data.search_results = [];

		var searchText =
			(input.search_text || '').trim();


		if (!searchText) {
			return;
		}


		var keyword =
			'%' + searchText + '%';


		// =================================================
		// SEARCH PLACEMENT OPPORTUNITIES
		// =================================================

		var opportunities =
			new GlideRecord(
				'x_snc_campus360_placement_opportunity'
			);


		opportunities.addQuery(
			'company',
			companySysId
		);


		var opportunityQuery =
			opportunities.addQuery(
				'opportunity_title',
				'LIKE',
				searchText
			);

		opportunityQuery.addOrCondition(
			'opportunity_id',
			'LIKE',
			searchText
		);

		opportunityQuery.addOrCondition(
			'job_description',
			'LIKE',
			searchText
		);

		opportunityQuery.addOrCondition(
			'location',
			'LIKE',
			searchText
		);


		opportunities.orderByDesc(
			'sys_created_on'
		);

		opportunities.setLimit(5);

		opportunities.query();


		while (opportunities.next()) {

			data.search_results.push({

				type: 'Opportunity',

				title:
					opportunities.getValue(
						'opportunity_title'
					),

				subtitle:
					opportunities.getValue(
						'opportunity_id'
					) +
					' • ' +
					opportunities.getDisplayValue(
						'status'
					),

				page:
					'campus360_recruiter_opportunities_new'

			});

		}


		// =================================================
		// SEARCH APPLICATIONS
		// =================================================

		var applications =
			new GlideRecord(
				'x_snc_campus360_student_application'
			);


		applications.addQuery(
			'opportunity.company',
			companySysId
		);


		var applicationQuery =
			applications.addQuery(
				'application_id',
				'LIKE',
				searchText
			);


		applicationQuery.addOrCondition(
			'student.name',
			'LIKE',
			searchText
		);


		applications.setLimit(5);

		applications.query();


		while (applications.next()) {

			var studentName = 'Student';

			if (applications.student) {

				studentName =
					applications.student.getDisplayValue();

			}


			data.search_results.push({

				type: 'Application',

				title:
					studentName,

				subtitle:
					applications.getValue(
						'application_id'
					) +
					' • ' +
					applications.getDisplayValue(
						'application_status'
					),

				page:
					'campus360_recruiter_applications_new'

			});

		}


		// =================================================
		// SEARCH STUDENTS
		// =================================================

		var students =
			new GlideRecord(
				'x_snc_campus360_student'
			);


		if (students.isValid()) {

			var studentQuery =
				students.addQuery(
					'name',
					'LIKE',
					searchText
				);

			studentQuery.addOrCondition(
				'student_id',
				'LIKE',
				searchText
			);


			students.setLimit(5);

			students.query();


			while (students.next()) {

				data.search_results.push({

					type: 'Student',

					title:
						students.getValue('name'),

					subtitle:
						students.getValue(
							'student_id'
						),

					page:
						'campus360_applications'

				});

			}

		}


		return;

	}

    // -----------------------------------------
    // PLACEMENT OPPORTUNITIES
    // -----------------------------------------

    var opportunities = new GlideRecord(
        'x_snc_campus360_placement_opportunity'
    );

    opportunities.addQuery('company', companySysId);
    opportunities.addQuery('status', 'Open');
    opportunities.query();

    data.opportunity_count = opportunities.getRowCount();

	// -----------------------------------------
	// PLACEMENT OPPORTUNITIES LIST
	// -----------------------------------------

	data.opportunities = [];

	var opportunityList = new GlideRecord(
		'x_snc_campus360_placement_opportunity'
	);

	opportunityList.addQuery('company', companySysId);
	opportunityList.addQuery('status', 'Open');
	opportunityList.orderByDesc('sys_created_on');
	opportunityList.setLimit(2);
	opportunityList.query();

	while (opportunityList.next()) {

		var opportunity = {};

		opportunity.opportunity_id =
			opportunityList.getValue('opportunity_id');

		opportunity.title =
			opportunityList.getValue('opportunity_title');

		opportunity.type =
			opportunityList.getDisplayValue('opportunity_type');

		opportunity.location =
			opportunityList.getValue('location');

		opportunity.ctc =
			opportunityList.getValue('ctc_stipend');

		var deadline = opportunityList.getValue('application_deadline');

		if (deadline) {
			var deadlineGDT = new GlideDateTime(deadline);
			opportunity.deadline = deadlineGDT.getDate().getByFormat('dd MMM yyyy');
		} else {
			opportunity.deadline = '';
		}

		opportunity.status =
			opportunityList.getDisplayValue('status');

		data.opportunities.push(opportunity);
	}


    // -----------------------------------------
    // STUDENT APPLICATIONS
    // -----------------------------------------

    var applications = new GlideRecord(
        'x_snc_campus360_student_application'
    );

    // Application -> Opportunity -> Company
    applications.addQuery(
        'opportunity.company',
        companySysId
    );

    applications.query();

    data.application_count = applications.getRowCount();

	// -----------------------------------------
	// APPLICATION PIPELINE
	// -----------------------------------------

	// PENDING
	var pending = new GlideAggregate(
		'x_snc_campus360_student_application'
	);

	pending.addQuery(
		'opportunity.company',
		companySysId
	);

	pending.addQuery(
		'application_status',
		'Pending'
	);

	pending.addAggregate('COUNT');
	pending.query();

	data.pending_count = 0;

	if (pending.next()) {
		data.pending_count = parseInt(
			pending.getAggregate('COUNT'),
			10
		);
	}


	// SUBMITTED
	var submitted = new GlideAggregate(
		'x_snc_campus360_student_application'
	);

	submitted.addQuery(
		'opportunity.company',
		companySysId
	);

	submitted.addQuery(
		'application_status',
		'Submitted'
	);

	submitted.addAggregate('COUNT');
	submitted.query();

	data.submitted_count = 0;

	if (submitted.next()) {
		data.submitted_count = parseInt(
			submitted.getAggregate('COUNT'),
			10
		);
	}


	// SHORTLISTED
	var shortlisted = new GlideAggregate(
		'x_snc_campus360_student_application'
	);

	shortlisted.addQuery(
		'opportunity.company',
		companySysId
	);

	shortlisted.addQuery(
		'application_status',
		'Shortlisted'
	);

	shortlisted.addAggregate('COUNT');
	shortlisted.query();

	data.shortlisted_count = 0;

	if (shortlisted.next()) {
		data.shortlisted_count = parseInt(
			shortlisted.getAggregate('COUNT'),
			10
		);
	}


	// SELECTED
	var selected = new GlideAggregate(
		'x_snc_campus360_student_application'
	);

	selected.addQuery(
		'opportunity.company',
		companySysId
	);

	selected.addQuery(
		'application_status',
		'Selected'
	);

	selected.addAggregate('COUNT');
	selected.query();

	data.selected_count = 0;

	if (selected.next()) {
		data.selected_count = parseInt(
			selected.getAggregate('COUNT'),
			10
		);
	}


	// REJECTED
	var rejected = new GlideAggregate(
		'x_snc_campus360_student_application'
	);

	rejected.addQuery(
		'opportunity.company',
		companySysId
	);

	rejected.addQuery(
		'application_status',
		'Rejected'
	);

	rejected.addAggregate('COUNT');
	rejected.query();

	data.rejected_count = 0;

	if (rejected.next()) {
		data.rejected_count = parseInt(
			rejected.getAggregate('COUNT'),
			10
		);
	}


	// -----------------------------------------
	// TOTAL APPLICATIONS
	// -----------------------------------------

	// Always use the actual application record count
	data.total_application_count =
		data.application_count;
	// -----------------------------------------
	// RECENT APPLICATIONS
	// -----------------------------------------

	var recentApplications = new GlideRecord(
		'x_snc_campus360_student_application'
	);

	recentApplications.addQuery(
		'opportunity.company',
		companySysId
	);

	recentApplications.orderByDesc('applied_date');
	recentApplications.setLimit(5);
	recentApplications.query();

	data.recent_applications = [];

	while (recentApplications.next()) {

		var application = {};

		// Application ID
		application.application_id =
			recentApplications.getValue('application_id');

		// Student
		if (recentApplications.student) {
			application.student_name =
				recentApplications.student.getDisplayValue();
		} else {
			application.student_name = 'Student';
		}

		// Opportunity / Role
		if (recentApplications.opportunity) {

			var opportunityGR = recentApplications.opportunity.getRefRecord();

			if (opportunityGR.isValidRecord()) {
				application.role =
					opportunityGR.getValue('opportunity_title');
			} else {
				application.role = 'Placement Opportunity';
			}

		} else {
			application.role = 'Placement Opportunity';
		}

		// Application status
		application.status =
			recentApplications.getDisplayValue('application_status');

		// Applied date
		application.applied_date =
			recentApplications.getDisplayValue('applied_date');

		data.recent_applications.push(application);
	}

	// -----------------------------------------
	// RECRUITER INTERVIEWS
	// -----------------------------------------

	var interviews = new GlideRecord(
		'x_snc_campus360_recruiter_interview'
	);

	// Interview -> Opportunity -> Company
	interviews.addQuery(
		'opportunity.company',
		companySysId
	);

	// Count only scheduled interviews
	interviews.addQuery('status', 'scheduled');

	interviews.query();

	data.interview_count = interviews.getRowCount();

	// -----------------------------------------
	// UPCOMING INTERVIEWS
	// -----------------------------------------

	var interviews = new GlideRecord('x_snc_campus360_recruiter_interview');

	interviews.addQuery('opportunity.company', companySysId);
	interviews.addQuery('interview_date', '>=', new GlideDateTime());
	interviews.orderBy('interview_date');
	interviews.setLimit(2);
	interviews.query();

	data.upcoming_interviews = [];

	while (interviews.next()) {

		var interview = {};

		interview.interview_id = interviews.getValue('interview_id');
		interview.interview_date = interviews.getValue('interview_date');
		interview.interviewer = interviews.getValue('interviewer');
		interview.interview_mode = interviews.getDisplayValue('interview_mode');
		interview.meeting_link = interviews.getValue('meeting_link');
		interview.status = interviews.getDisplayValue('status');

		// Student
		if (interviews.student) {
			interview.student_name =
				interviews.student.getDisplayValue();
		} else {
			interview.student_name = 'Student';
		}

		// Opportunity
		if (interviews.opportunity) {
			interview.opportunity_title =
				interviews.opportunity.getDisplayValue();
		} else {
			interview.opportunity_title = 'Placement Interview';
		}

		data.upcoming_interviews.push(interview);
	}

	// -----------------------------------------
	// OFFERS MADE
	// -----------------------------------------

	var offers = new GlideAggregate(
		'x_snc_campus360_student_application'
	);

	offers.addQuery(
		'opportunity.company',
		companySysId
	);

	offers.addQuery(
		'offer_status',
		'Offered'
	);

	offers.addAggregate('COUNT');

	offers.query();

	data.offer_count = 0;

	if (offers.next()) {

		data.offer_count =
			parseInt(
				offers.getAggregate('COUNT'),
				10
			);

	}


})();
